fun parsePort(raw: String): Result<Int> =
    raw.trim().toIntOrNull()?.takeIf { it > 0 }
        ?.let { Result.success(it) }
        ?: Result.failure(NumberFormatException(raw))
val port = parsePort(raw).map { it + 1 }.getOrElse { 8080 }

